                    text: 'GNUnet、I2P、Hyphanet（原 Freenet）和 ZeroNet 经常被放进同一张“匿名网络”清单，但它们不是同一种东西，也不能互相替代。它们的设计目标、身份模型、路由方式和失败模式都不同；把“去中心化”“P2P”“匿名”当成同义词，会让人低估真正暴露的那一层。',
