                    text: 'GNUnet、I2P、Hyphanet（原 Freenet）和 ZeroNet 經常被放進同一張「匿名網路」清單，但它們不是同一種東西，也不能互相替代。它們的設計目標、身分模型、路由方式和失敗模式都不同；把「去中心化」「P2P」「匿名」當成同義詞，會讓人低估真正暴露的那一層。',
