                        'I2P：身分是 destination（公鑰）；大蒜路由 + 單向隧道；用途是 eepsite 和內部 P2P；普通對端看不到你的真實 IP，但本機 router 和 ISP 知道你在跑 I2P；沒有預設出口；生態較小；不保護端點內容和流量特徵。',
